"""Stage4 consumes retained real source data, without acquiring substitute models."""
import json
from nyc.download import ROOT,sha,atomic_json,now
def main():
 sources=json.loads((ROOT/'data/manifests/sources.json').read_text())
 policy={'id':'stage4-strict-building-evidence-v1','semantic_levels':['outline_only','outline_plus_resolved_relative_height','reliable_roof_volume','verified_facade_model'],'render_lod_is_independent':True,'current_semantic_level':'outline_only','source_outline_kind':'Building Footprints metadata description: full perimeter viewed directly from above; ground wall line not guaranteed','canonical_height_policy':'raw source HEIGHT_ROOF retained; foot subtype unresolved => canonical metre value null','unknown_height':'no default height, no parcel floors * assumed storey height','strict_mode':'only source outlines; placeholder1003 excluded','hypothesis_mode':{'default':False,'label':'explicit source-height hypothesis, not verified building','factor':.3048,'unit_assumption':'international foot, NOT a source fact','comparison_factor':1200/3937,'base':'WGS84 ellipsoid display reference +0.25m, NOT ground','roof':'open, no cap','components':'source polygon parts only, no invented towers/podia/setbacks/skybridges/plant rooms','excluded_body_codes':{'1000':'parking','1001':'canopy','1002':'tank','1003':'placeholder','1006':'cantilever unknown base','2110':'skybridge unknown deck','5100':'construction, incomplete shape'}},'roof_derivation':'no LAS/LAZ acquired; no density/residual/boundary metrics can honestly be reported; do not generate procedural roof detail','legacy_model':'2014 source, Feet/US survey foot and per-object identity/date matching unresolved; zero current matches','pluto':'parcel-scoped candidates only; no per-building height, floor, date or use assignment','world_vertical':'unresolved NAD83 realization and building ground datum; no canonical ECEF body placement','field_evidence':{'position':{'source':'nyc-building-footprints:SHAPE','status':'source_explicit','independently_verified':False},'footprint':{'source':'nyc-building-footprints:SHAPE','status':'source_explicit_or_repair_derived','independently_verified':False},'height':{'source':'nyc-building-footprints:HEIGHT_ROOF','status':'source_explicit_value_but_unit_unresolved','canonical_metres':None},'roof':{'source':None,'status':'unknown'},'facade':{'source':None,'status':'unknown'},'age':{'source':'CONSTRUCTION_YEAR and LAST_EDITED_DATE are not observation date','status':'mixed_record_fields; observation unknown'}}}
 selected=[s for s in sources['sources']if s['id']in ['nyc-building-footprints','nyc-3d-model','nyc-pluto','pluto']]
 record={'schema_version':4,'at':now(),'capture_version':'2026-10-27-city','input':'second-stage retained real five-borough footprint SQLite; read-only','new_network_downloads_this_stage':0,'source_registry':sources,'sources_directly_consumed':selected,'coordinate_contract':'scripts/nyc/coordinates.py + docs/COORDINATES.md','representation_policy':policy,'input_sha256':{'data/processed/city/buildings.sqlite':sha(ROOT/'data/processed/city/buildings.sqlite'),'data/raw/catalog/footprints-metadata.response':sha(ROOT/'data/raw/catalog/footprints-metadata.response'),'data/intermediate/extracted/nyc_pluto_26v2_csv/pluto_26v2.csv':sha(ROOT/'data/intermediate/extracted/nyc_pluto_26v2_csv/pluto_26v2.csv')},'processor_sha256':{p:sha(ROOT/p)for p in ['scripts/build_buildings.py','scripts/nyc/buildings.py','scripts/nyc/coordinates.py','scripts/audit_buildings.py','scripts/select_building_review.py']},'license':'NYC Open Data Terms of Use; not a public-domain inference; source notices retained','downloads_dates':'original download receipts retained; processing timestamp above is NOT new observation/download date'}
 atomic_json(ROOT/'data/manifests/stage4/sources.json',record);atomic_json(ROOT/'data/manifests/stage4/representation-policy.json',policy)
 for dest in ['assets/buildings-pilot-lower','assets/buildings-pilot-midtown','assets/buildings-city']:
  atomic_json(ROOT/dest/'sources.json',record);atomic_json(ROOT/dest/'representation-policy.json',policy)
 # Compare every previously inventoried raw byte and major normalized input.
 missing=[];changed=[];count=0;large=[]
 for line in(ROOT/'data/manifests/files.jsonl').read_text().splitlines():
  item=json.loads(line);path=ROOT/item['path']
  if item['path'].startswith('data/raw/'):
   count+=1
   if not path.exists():missing.append(item['path'])
   elif sha(path)!=item['sha256']:changed.append(item['path'])
  if item['path']in ['data/processed/city/buildings.sqlite','data/processed/context/context.gpkg','data/raw/supporting/nyc_pluto_26v2_csv.zip','data/raw/supporting/nyc_3dmodel_mn01.zip']:large.append({'path':item['path'],'sha256_unchanged':path.exists()and sha(path)==item['sha256']})
 if missing or changed or any(not x['sha256_unchanged']for x in large):raise ValueError('retained input integrity changed')
 atomic_json(ROOT/'reports/stage4/input-integrity.json',{'prior_raw_checked':count,'missing':missing,'changed':changed,'large_inputs':large})
 print('SOURCES_AND_INPUT_INTEGRITY',count,'unchanged',flush=True)
if __name__=='__main__':main()
